using System.IO;
using System.Text;
using Xunit;

namespace Fluent.Pdf.Contract.Tests;
public sealed class SecurityRegressionTests
{
    // Original public-credential fixtures independently emitted by MuPDF 1.26.6. No imported implementation.
    private const string Compressed = "";
    private const string Incremental = "";
    [Theory]
    [InlineData(false)]
    [InlineData(true)]
    public void IndependentCompressedObjectsAndStableEncryptedHistoryDecryptOnce(bool history)
    {
        var bytes = Convert.FromBase64String(history ? Incremental : Compressed);
        using var input = new MemoryStream(bytes);
        Assert.Equal("Syntax.EncryptionProviderRequired", Assert.Throws<PdfException>(() => PdfSyntax.Read(input)).Diagnostic.Code);
        input.Position = 0;
        using var output = new MemoryStream();
        using var password = new PdfPassword(Encoding.ASCII.GetBytes("user"));
        var result = PdfSecurity.DecryptWithPassword(input, output, password);
        Assert.Equal(PdfAuthenticationRole.User, result.Role);
        output.Position = 0;
        using var document = Pdf.Open(output);
        Assert.Single(document.Pages);
        Assert.Equal(history ? "Original encrypted revision two" : "Original compressed security fixture", PdfMetadata.Inspect(document.CreateSnapshot()).Text["Title"]);
        output.Position = 0;
        Assert.False(PdfSyntax.Read(output).Revisions[0].Trailer.Entries.ContainsKey("Encrypt"));
    }

    [Fact]
    public void SharedInputExpansionAndOutputBudgetsFailBeforePublishing()
    {
        using var input = new MemoryStream(Convert.FromBase64String(Compressed));
        using var output = new MemoryStream();
        using var password = new PdfPassword(Encoding.ASCII.GetBytes("user"));
        foreach (var limits in new[]
        {
            new PdfResourceLimits(maximumInputBytes: 1),
            new PdfResourceLimits(maximumExpandedBytes: 1024),
            new PdfResourceLimits(maximumOutputBytes: 1)
        }

        )
        {
            input.Position = 0;
            Assert.StartsWith("Limit.", Assert.Throws<PdfException>(() => PdfSecurity.DecryptWithPassword(input, output, password, policy: new(limits: limits))).Diagnostic.Code);
            Assert.Equal(0, output.Length);
        }
    }
}
